import sys
import json
import xml.etree.ElementTree as ET
from typing import Dict, Optional

def parse_xml_file(xml_path: str) -> ET.Element:
    try:
        tree = ET.parse(xml_path)
        return tree.getroot()
    except ET.ParseError as e:
        sys.stderr.write(f"ERROR: Failed to parse XML file: {e}\n")
        sys.exit(1)
    except FileNotFoundError:
        sys.stderr.write(f"ERROR: File not found: {xml_path}\n")
        sys.exit(1)

def evaluate_expression(expr: str, field_values: Dict[str, float]) -> Optional[float]:
    try:
        # Replace field names with their values in the expression
        for name, value in field_values.items():
            expr = expr.replace(name, str(value))
        # Evaluate the expression safely
        return eval(expr)
    except (NameError, ZeroDivisionError, SyntaxError, ValueError) as e:
        return None

def process_report(xml_root: ET.Element) -> Dict[str, float]:
    field_values = {}
    for field in xml_root.findall('field'):
        name = field.get('name')
        expr = field.get('expr')
        if name is None or expr is None:
            continue

        value = evaluate_expression(expr, field_values)
        if value is not None:
            field_values[name] = value
            sys.stderr.write(f"INFO: Field '{name}' value recorded: {value}\n")
        else:
            sys.stderr.write(f"ERROR: Field '{name}' value not recorded\n")

    return field_values

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("ERROR: Usage: python exprreport.py <xml_file>\n")
        sys.exit(1)

    xml_path = sys.argv[1]
    xml_root = parse_xml_file(xml_path)
    field_values = process_report(xml_root)

    if not field_values:
        sys.exit(1)
    else:
        sys.exit(0)

    sys.stdout.write(json.dumps(field_values))

if __name__ == "__main__":
    main()

import sys
import json
import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation

def parse_expression(expr, field_values):
    try:
        # Replace field names with their values
        for name in field_values:
            if name in expr:
                expr = expr.replace(name, str(field_values[name]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'Decimal': Decimal})
    except (NameError, ZeroDivisionError, InvalidOperation, SyntaxError):
        return None

def process_xml_file(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"ERROR: Invalid XML file: {e}", file=sys.stderr)
        sys.exit(1)

    field_values = {}
    recorded_fields = []

    for field in root.findall('field'):
        name = field.get('name')
        expr = field.get('expr')

        if not name or not expr:
            print(f"ERROR {name}", file=sys.stderr)
            continue

        value = parse_expression(expr, field_values)
        if value is not None:
            try:
                field_values[name] = float(value)
                recorded_fields.append(name)
                print(f"INFO {name} {value}", file=sys.stderr)
            except ValueError:
                print(f"ERROR {name}", file=sys.stderr)
        else:
            print(f"ERROR {name}", file=sys.stderr)

    if not recorded_fields:
        sys.exit(1)
    else:
        sys.exit(0)

    output = {name: field_values[name] for name in recorded_fields}
    print(json.dumps(output))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python exprreport.py <xml_file>", file=sys.stderr)
        sys.exit(1)

    process_xml_file(sys.argv[1])

import sys
import json
import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation

def parse_expr(expr, field_values):
    try:
        # Replace field names with their values
        for name, value in field_values.items():
            expr = expr.replace(name, str(value))
        # Evaluate the expression
        return eval(expr, {'__builtins__': None}, {})
    except (NameError, ZeroDivisionError, TypeError, ValueError, InvalidOperation):
        return None

def process_xml_file(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()

    field_values = {}
    has_value = False

    for field in root.findall('field'):
        name = field.get('name')
        expr = field.get('expr')

        if expr is None:
            print(f"ERROR {name}", file=sys.stderr)
            continue

        value = parse_expr(expr, field_values)
        if value is not None:
            field_values[name] = float(value)
            has_value = True
            print(f"INFO {name} {value}", file=sys.stderr)
        else:
            print(f"ERROR {name}", file=sys.stderr)

    if has_value:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)
    process_xml_file(sys.argv[1])
